const retry = () => {
    if (disposed || loadState.status === 'ready') return
    loadState = { status: 'loading' }
    publish(asks)
    void refresh()
  }

const refresh = async (eventSeq = 0) => {
    const mine = ++generation
    const removed = new Set<string>()
    removedDuringRefresh.add(removed)
    try {
      const list = (await context.call('quirky.ask/list', { pendingOnly: true })) as Ask[]
      if (disposed || mine < appliedGeneration) return
      appliedGeneration = mine
      watermark = Math.max(watermark, eventSeq)
      for (const ask of list) watermark = Math.max(watermark, ask.seq)
      const live = list.filter((ask) => !removed.has(ask.id) && !resolvedIds.has(ask.id))
      prunePreviewsForList(new Set(live.map((ask) => ask.id)))
      if (loadState.status !== 'ready') loadState = { status: 'ready' }
      publish(
        live.filter((ask) => !ask.queued).sort((a, b) => a.createdAt - b.createdAt || a.id.localeCompare(b.id)),
        live.filter((ask) => ask.queued).length
      )
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      context.log(`could not list asks: ${message}`)
      if (!disposed && mine === generation && mine >= appliedGeneration && loadState.status !== 'ready') {
        loadState = { status: 'failed', message }
        publish(asks)
      }
    } finally {
      removedDuringRefresh.delete(removed)
    }
  }

const openDelegatedQuestion = async () => {
    if (!ask.sessionId) {
      context.toast('Could not open delegated question', 'The exact delegated session is unavailable.')
      return
    }
    setBusy(true)
    try {
      let worktreeId = ask.worktreeId
      if (!worktreeId) {
        const session = await context.call('quirky.session/get', { session: ask.sessionId })
        if (typeof session !== 'object' || session === null || !('worktreeId' in session) || typeof session.worktreeId !== 'string') {
          throw new Error('The delegated session has no worktree view.')
        }
        worktreeId = session.worktreeId
      }
      context.openView('view:quirky.session/worktree', { worktree: worktreeId, session: ask.sessionId })
    } catch (error) {
      context.toast('Could not open delegated question', error instanceof Error ? error.message : String(error))
    } finally {
      setBusy(false)
    }
  }

const change = (questionId: string, draft: QuestionDraft) => {
    latest.current = { ...latest.current, [questionId]: draft }
    setDrafts(latest.current)
    setErrors(({ [questionId]: _cleared, ...rest }) => rest)
    scheduleSave()
  }

const scheduleSave = () => {
    cancelSave()
    saveTimer.current = setTimeout(() => {
      saveTimer.current = null
      context
        .call('quirky.ask/updatePartial', { askId: ask.id, partial: draftsToPartial(latest.current, ask.spec) })
        .catch((error: unknown) => context.log(`could not save draft: ${error instanceof Error ? error.message : String(error)}`))
    }, SAVE_DELAY_MS)
  }

const submit = () => {
    const submission = buildSubmission(ask.spec, drafts)
    if (!submission.ok) {
      setErrors(submission.errors)
      return
    }
    setErrors({})
    return attempt(
      () => context.call('quirky.ask/answer', { askId: ask.id, answers: submission.answers, skipped: submission.skipped }) as Promise<AskEnvelope>,
      'Could not answer'
    )
  }

